def _validate_flag_dict(value: object, name: str) -> None:
    """Raise TypeError if *value* is not a dict[str, bool]."""
    if not isinstance(value, dict):
        raise TypeError(f"{name} must be a dict, got {type(value).__name__}")
    for k, v in value.items():
        if not isinstance(k, str):
            raise TypeError(
                f"All keys in {name} must be strings, got key {k!r} of type {type(k).__name__}"
            )
        if not isinstance(v, bool):
            raise TypeError(
                f"All values in {name} must be bools, got {name}[{k!r}] = {v!r} of type {type(v).__name__}"
            )


def _validate_segments(segments: object) -> None:
    """Raise TypeError if *segments* is not dict[str, dict[str, bool]]."""
    if not isinstance(segments, dict):
        raise TypeError(f"segments must be a dict, got {type(segments).__name__}")
    for seg_name, seg_flags in segments.items():
        if not isinstance(seg_name, str):
            raise TypeError(
                f"All segment keys must be strings, got {seg_name!r} of type {type(seg_name).__name__}"
            )
        _validate_flag_dict(seg_flags, f"segments[{seg_name!r}]")


def _validate_user(user: object) -> None:
    """Raise TypeError/ValueError if *user* is not a well-formed user dict."""
    if not isinstance(user, dict):
        raise TypeError(f"user must be a dict, got {type(user).__name__}")

    if "segments" in user:
        seg_list = user["segments"]
        if not isinstance(seg_list, list):
            raise TypeError(
                f"user['segments'] must be a list, got {type(seg_list).__name__}"
            )
        for i, seg in enumerate(seg_list):
            if not isinstance(seg, str):
